tools.example:
model.component("comp1").physics("emw").create("port1", "Port", 2);
model.component("comp1").physics("emw").feature("port1").selection().set(new int[]{1});
model.component("comp1").physics("emw").feature("port1").set("PortType", "Rectangular");
model.component("comp1").physics("emw").feature("port1").set("PortExcitation", "on");
// Application Libraries: RF_Module/Transmission_Lines_and_Waveguides/h_bend_waveguide_3d, RF_Module/Ferrimagnetic_Devices/circulator (2D)

model.component("comp1").physics("emw").create("port1", "Port", 1);
model.component("comp1").physics("emw").feature("port1").set("PortType", "Coaxial");
model.component("comp1").physics("emw").feature("port1").set("PortExcitation", "on");
// 2D axisymmetric feed: Application Library RF_Module/Antennas/conical_antenna

model.component("comp1").physics("emw").feature("port1").set("PortType", "Circular");
model.component("comp1").physics("emw").feature("port1").set("CircularPortModeNumber", "11");
model.component("comp1").physics("emw").feature("port1").create("cportv1", "CircularPortReferenceAxis", 0);
model.component("comp1").physics("emw").feature("port1").feature("cportv1").selection().set(new int[]{3, 5});
// Application Libraries: RF_Module/Tutorials/polarized_circular_ports, RF_Module/Antennas/corrugated_circular_horn_antenna

Waveguide adapter with one rectangular and one numeric (ridged) port:
model.component("comp1").physics("emw").feature("port2").set("PortType", "Numeric");
model.study("std1").create("bma2", "BoundaryModeAnalysis");
model.study("std1").feature("bma2").set("PortName", "2");
model.study("std1").feature("bma2").set("modeFreq", "7[GHz]");
// Application Libraries: RF_Module/Transmission_Lines_and_Waveguides/waveguide_adapter, cpw_numeric_tem_port, RF_Module/Filters/notch_filter_srr

model.component("comp1").physics("emw").feature("port1").set("PortType", "TEM");
model.component("comp1").physics("emw").feature("port1").create("gnd1", "Ground", 1);
model.component("comp1").physics("emw").feature("port1").create("pot1", "ElectricPotential", 1);
model.study("std1").create("tbma", "TEMBoundaryModeAnalysis");
// Application Libraries: RF_Module/Transmission_Lines_and_Waveguides/microstrip_line_tem_via, microstrip_line_tem_differential

model.component("comp1").physics("emw").feature("port1").set("PortType", "Periodic");
model.component("comp1").physics("emw").feature("port1").set("Polarization", "LinearPol");
model.component("comp1").physics("emw").feature("port1").set("alpha1_inc", "theta");
model.component("comp1").physics("emw").feature("port1").runCommand("addDiffractionOrders");
// Application Libraries: RF_Module/Tutorials/plasmonic_wire_grating, RF_Module/Tutorials/hexagonal_grating

model.component("comp1").physics("ewfd").feature("ps1").feature("pport1").create("dport3", "DiffractionOrder", 1);
model.component("comp1").physics("ewfd").feature("ps1").feature("pport1").feature("dport3").set("mOrder", "-1");
// reflectance of order -1: ewfd.Rorder_n1; Application Libraries: Wave_Optics_Module/Applications/plasmonic_wire_grating, Ray_Optics_Module/Verification_Examples/diffraction_grating

Interior slit ports on a frequency selective surface cell backed by PMLs:
model.component("comp1").physics("emw").feature("port1").set("PortSlit", "1");
model.component("comp1").physics("emw").feature("port1").set("SlitType", "DomainBacked");
// Application Library: RF_Module/EMI_EMC_Applications/frequency_selective_surface_csrr

Center-fed dipole: a Uniform lumped port across the feed gap, Cable terminal, V0 = 1 V, Zref = 50 ohm; evaluate emw.Zport_1 and emw.S11dB.
model.component("comp1").physics("emw").create("lport1", "LumpedPort", 2);
model.component("comp1").physics("emw").feature("lport1").set("PortType", "Uniform");
// Application Libraries: RF_Module/Antennas/dipole_antenna, RF_Module/Antenna_Arrays/microstrip_patch_antenna_inset (User defined), RF_Module/Filters/cpw_bandpass_filter (Multielement uniform)

model.component("comp1").physics("emw").create("lelement1", "LumpedElement", 2);
model.component("comp1").physics("emw").feature("lelement1").set("Zelement", "100[ohm]");
// isolation resistor of a Wilkinson divider: RF_Module/Couplers_and_Power_Dividers/wilkinson_power_divider; time domain: RF_Module/ESD_and_Lightning_Surge/esd_test_pcb

model.component("comp1").physics("emw").create("mms1", "MixedModeSparameters", -1);
model.component("comp1").physics("emw").feature("mms1").set("portA", "1");
model.component("comp1").physics("emw").feature("mms1").set("portB", "3");
// plot emw.Sdd21dB and emw.Scd21dB; Application Library: RF_Module/EMI_EMC_Applications/microstrip_line_mixed_mode

model.component("comp1").physics("emw").prop("PortSweepSettings").set("useSweep", true);
model.component("comp1").physics("emw").prop("PortSweepSettings").set("ExportTouchstone", true);
// then click Configure Sweep Settings (adds param PortName and a Parametric Sweep)
// Application Library: RF_Module/Transmission_Lines_and_Waveguides/h_bend_waveguide_3d

model.study("std1").create("frawe", "FrequencyAdaptive");
model.study("std1").feature("frawe").set("plist", "range(3.2[GHz],0.5[MHz],3.5[GHz])");
model.study("std1").feature("frawe").set("awefunctype", "usercontrolled");
model.study("std1").feature("frawe").setIndex("awefunc", "abs(comp1.emw.S21)", 0);
// Application Libraries: RF_Module/Filters/cylindrical_cavity_filter_evanescent, RF_Module/Passive_Devices/rf_coil, RF_Module/Couplers_and_Power_Dividers/wilkinson_power_divider

model.study("std1").create("tbma", "TEMBoundaryModeAnalysis");
model.study("std1").create("freq", "Frequency");
model.study("std1").feature("freq").set("plist", "range(1[GHz],0.5[GHz],10[GHz])");
// Application Libraries: RF_Module/Transmission_Lines_and_Waveguides/microstrip_line_tem_via, microstrip_line_tem_differential

model.study("std1").create("eig", "Eigenfrequency");
model.study("std1").feature("eig").set("shift", "3.3[GHz]");
model.study("std1").feature("eig").set("eigwhich", "lr");
// Global Evaluation: emw.freq, emw.Qfactor
// Application Libraries: RF_Module/Verification_Examples/cavity_resonators, RF_Module/Filters/cascaded_cavity_filter, Wave_Optics_Module/Verification_Examples/whispering_gallery_mode_resonator

model.result().create("pg2", "PlotGroup1D");
model.result("pg2").create("glob1", "Global");
model.result("pg2").feature("glob1").set("expr", new String[]{"emw.S11dB", "emw.S21dB"});
// Application Libraries: RF_Module/Couplers_and_Power_Dividers/branch_line_coupler, RF_Module/Antennas/vivaldi_antenna (emw.VSWR_1)

model.result().dataset().create("af1", "ArrayFactor");
model.result().dataset("af1").set("data", "dset1");
model.result().dataset("af1").setIndex("size", 8, 0);
model.result().dataset("af1").setIndex("size", 8, 1);
// Application Library: RF_Module/Antenna_Arrays/microstrip_patch_antenna_periodic

model.result().create("pg3", "SmithGroup");
model.result("pg3").create("rgr1", "ReflectionGraph");
model.result("pg3").feature("rgr1").set("expr", new String[]{"emw.S11"});
model.result("pg3").feature("rgr1").create("col1", "Color");
// default 'Smith Plot (emw)' in RF_Module/Antennas/conical_antenna and most port-driven RF models

model.result().export().create("exp1", "pg2", "rp1", "RadiationPattern");
model.result().export("exp1").set("filename", "C:/work/gain_pattern.txt");
model.result().export("exp1").run();
// default Radiation Pattern plots carry an Export Expressions subfeature with elevation/azimuth columns

model.result().create("pg3", "PlotGroup2D");
model.result("pg3").create("spot1", "SpotDiagram");
model.result("pg3").feature("spot1").set("circleactive", true);
model.result("pg3").feature("spot1").set("circleradiusexpr", "r_Airy");
model.result("pg3").feature("spot1").runCommand("createFocalPlaneDataset");
// Application Libraries: Ray_Optics_Module/Lenses_Cameras_and_Telescopes/double_gauss_lens, gregory_maksutov_telescope, hubble_space_telescope

model.result("pg4").create("oab1", "OpticalAberration");
model.result("pg4").feature("oab1").set("filterreleaseactive", true);
model.result("pg4").feature("oab1").runCommand("createReferenceHemisphereDataset");
// Application Libraries: Ray_Optics_Module/Lenses_Cameras_and_Telescopes/double_gauss_lens, Ray_Optics_Module/Structural_Thermal_Optical_Performance_Analysis/newtonian_telescope_structural_analysis

model.result().dataset().create("ip1", "IntersectionPoint3D");
model.result().dataset("ip1").set("data", "ray1");
// used by the Spot Diagram of Ray_Optics_Module/Lenses_Cameras_and_Telescopes/alvarez_lens; Ray Bin used in Ray_Optics_Module/Spectrometers_and_Monochromators/czerny_turner_monochromator
